<script setup>
const props = defineProps({
    // 年份文字，如 2024
    year: { type: [String, Number], default: '' },
    // 手机端轮播：当前活动卡片高亮
    active: { type: Boolean, default: false },
    // PC 端：hover 时高亮（依赖父级 .group）
    pc: { type: Boolean, default: false }
})

const rowClass = computed(() => {
    if (props.pc) return 'flex items-center transition-all duration-300 group-hover:justify-start'
    // 手机端：始终左对齐（与 PC hover 一致）
    return 'flex items-center gap-[8px]'
})

const textClass = computed(() => {
    if (props.pc) return 'md:group-hover:text-[64px] text-[#0043FF] group-hover:text-white text-[32px] md:text-[40px] transition-all duration-300'
    return 'text-[32px] ' + (props.active ? 'text-white text-[40px]' : 'text-[#0043FF]')
})
</script>

<style scoped>
/* 月桂图标跟随文字颜色 */
.svg-year path {
    fill: currentColor;
    transition: fill 0.3s;
}
</style>
